local raw = redis.call('GET', KEYS[1]) if not raw then redis.call('SET', KEYS[1], '1', 'PX', window_ms) return {1, 1, window_ms} end
local current = tonumber(raw) local ttl = redis.call('PTTL', KEYS[1]) -- Refuse corrupt/persistent counters; do not silently reset their budget. if not current or current < 1 or current > 2147483647 or current % 1 ~= 0 or tostring(current) ~= raw or ttl < 0 then return {-1, 0, 0} end if current >= limit then return {0, current, ttl} end
current = redis.call('INCR', KEYS[1]) return {1, current, ttl}

def admit_flash_sale_attempt():
    if not settings.FLASH_SALE_ADMISSION_ENABLED:
        return

    limit = settings.FLASH_SALE_ADMISSION_LIMIT
    window_ms = settings.FLASH_SALE_ADMISSION_WINDOW_MS
    try:
        result = get_admission_redis_client().eval(
            ADMISSION_SCRIPT, 1, admission_key(), limit, window_ms,
        )
    except RedisError as error:
        # A timeout may follow a consumed permit; do not retry or refund an unknown result.
        logger.warning("Flash-sale admission failed: %s", type(error).__name__)
        raise _unavailable() from error

try:
    updated = Inventory.objects.filter(sku=sku, available_stock__gte=1).update(
        available_stock=F("available_stock") - 1,
        reserved_stock=F("reserved_stock") + 1,
    )
except DatabaseError as exc:
    # 仅将已知库存锁竞争转换为繁忙，不吞掉连接等其他数据库故障。
    if not exc.args or exc.args[0] not in (1205, 1213):
        raise
    raise OrderRuleError("stock_busy", "库存正在更新，请重试原请求。", 409) from exc
if updated != 1:
    raise OrderRuleError("insufficient_stock", "活动商品库存不足。", 409)
return Inventory.objects.get(sku=sku)
